#ifndef RING_BUFFER_HPP
#define RING_BUFFER_HPP

#include <cstddef>
#include <string>
#include <vector>

/* One logged event: when it happened, and what happened. */
struct Event {
    long long at = 0;      /* a timestamp; it is NOT always increasing */
    std::string text;      /* one word, no spaces */
};

/* A bounded first-in, first-out buffer of events.
 *
 * The PUBLIC part is the contract. main.cpp is written against exactly
 * these names and signatures, so changing one stops it compiling.
 *
 * Everything under `private:` is yours. The three members below are
 * what a ring buffer usually needs — a block of slots, where the
 * oldest one is, how many are in use, and from this milestone on
 * whether it overwrites — and you may replace them with anything that
 * behaves the same.
 */
class RingBuffer {
public:
    explicit RingBuffer(std::size_t capacity);

    std::size_t capacity() const;
    std::size_t size() const;
    bool empty() const;
    bool full() const;

    /* Adds `e` as the newest event. Returns false, and changes nothing
     * at all, when there is no room. */
    bool push(const Event& e);

    /* Removes the OLDEST event into `out`. Returns false when there is
     * nothing to remove, and leaves `out` alone. */
    bool pop(Event& out);

    /* The i-th oldest event still held. i < size(). */
    Event at(std::size_t i) const;

    /* Milestone 2. With overwriting on, a push into a full buffer
     * drops the oldest event to make room and succeeds. With it off —
     * which is how a buffer starts — a push into a full buffer refuses,
     * exactly as in milestone 1. */
    void set_overwrite(bool on);
    bool overwriting() const;

    /* How many events have been dropped to make room, over the whole
     * life of this buffer. A pop is not a drop. */
    std::size_t dropped() const;

private:
    std::size_t cap_;
    std::size_t start_ = 0;
    std::size_t count_ = 0;
    std::vector<Event> slots_;
    bool overwrite_ = false;
    std::size_t dropped_ = 0;
};

#endif

#include "ring_buffer.hpp"

/* Milestone 3 asks nothing of this file. It is milestone 2's answer,
   and it arrives carried forward from your own work if you did that
   one. Everything it already does is tested again here.
*/

RingBuffer::RingBuffer(std::size_t capacity)
    : cap_(capacity), slots_(capacity) {}

std::size_t RingBuffer::capacity() const {
    return cap_;
}

std::size_t RingBuffer::size() const {
    return count_;
}

bool RingBuffer::empty() const {
    return count_ == 0;
}

bool RingBuffer::full() const {
    return count_ == cap_;
}

bool RingBuffer::push(const Event& e) {
    if (full()) {
        if (!overwrite_) return false;
        /* Make room by throwing away the oldest. The slot it was in is
           where the new event goes, because start_ moves on by one and
           (start_ + count_) % cap_ is then that same slot. */
        start_ = (start_ + 1) % cap_;
        --count_;
        ++dropped_;
    }
    slots_[(start_ + count_) % cap_] = e;
    ++count_;
    return true;
}

bool RingBuffer::pop(Event& out) {
    if (empty()) return false;
    out = slots_[start_];
    start_ = (start_ + 1) % cap_;
    --count_;
    return true;
}

Event RingBuffer::at(std::size_t i) const {
    return slots_[(start_ + i) % cap_];
}

void RingBuffer::set_overwrite(bool on) {
    overwrite_ = on;
}

bool RingBuffer::overwriting() const {
    return overwrite_;
}

std::size_t RingBuffer::dropped() const {
    return dropped_;
}

/* Yours from this milestone on.
 *
 * Everything that was here in milestones 1 and 2 still has to work:
 * the hidden cases run those commands again. What is new is `report`,
 * and the branch for it is empty.
 */
#include <algorithm>
#include <iostream>
#include <sstream>
#include <string>

#include "ring_buffer.hpp"

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    std::size_t cap = 0;
    if (!(std::cin >> cap)) return 0;
    RingBuffer buf(cap);

    std::string line;
    std::getline(std::cin, line);          /* the rest of the capacity line */

    while (std::getline(std::cin, line)) {
        std::istringstream in(line);
        std::string cmd;
        if (!(in >> cmd)) continue;

        if (cmd == "push") {
            Event e;
            if (!(in >> e.at >> e.text)) continue;
            if (!buf.push(e)) std::cout << "full\n";
        } else if (cmd == "pop") {
            Event e;
            if (buf.pop(e)) std::cout << e.at << ' ' << e.text << '\n';
            else std::cout << "empty\n";
        } else if (cmd == "size") {
            std::cout << buf.size() << '/' << buf.capacity() << '\n';
        } else if (cmd == "overwrite") {
            std::string how;
            if (!(in >> how)) continue;
            buf.set_overwrite(how == "on");
        } else if (cmd == "dropped") {
            std::cout << buf.dropped() << '\n';
        } else if (cmd == "report") {
            /* your code here — the same events `dump` would print, in
             * order of when they HAPPENED rather than when they
             * arrived, and `(none)` when there are none.
             *
             * Two events with the same timestamp keep the order they
             * arrived in. buf.at(0) is the oldest arrival.
             */
        } else if (cmd == "dump") {
            if (buf.empty()) {
                std::cout << "(none)\n";
            } else {
                for (std::size_t i = 0; i < buf.size(); ++i) {
                    const Event e = buf.at(i);
                    std::cout << e.at << ' ' << e.text << '\n';
                }
            }
        }
    }
    return 0;
}
